content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-006

=== 用户原始指令 (query.txt) ===
帮我整个喂食卡片，点一下能跳app，能看天气，出粮卡了要红色提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个喂食卡片，点一下能跳app，能看天气，出粮卡了要红色提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "feeder": {
      "title": {
        "type": "string",
        "description": "宠物喂食设备名称",
        "sampleValue": "喂食机"
      },
      "statusText": {
        "type": "string",
        "description": "当前出粮状态，卡住时用于提醒",
        "sampleValue": "出粮卡住"
      },
      "statusColor": {
        "type": "string",
        "description": "当前出粮状态提醒色，异常时使用红色",
        "sampleValue": "#ffe84026"
      },
      "nextMealText": {
        "type": "string",
        "description": "下一次喂食时间摘要",
        "sampleValue": "下餐 18:30"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合表达当前天气摘要和天气入口。"
    }
  ]
}

